/* vm86(2) - Example showing structure setup and call pattern */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <sys/types.h>
#include <sys/vm86.h>

/* 
 * Note: The struct vm86_struct definition is highly kernel-version
 * and architecture dependent. A simplified, illustrative definition is used here
 * for compilation purposes. Real use requires precise kernel headers.
 */
struct vm86_struct {
    long regs[16]; 
    unsigned long flags;
    // ... other fields for segment registers, etc.
};

extern int vm86old(struct vm86_struct *info);

int main() {
    struct vm86_struct v86_context;

    // 1. Initialize the structure (crucial setup omitted for brevity)
    memset(&v86_context, 0, sizeof(v86_context));
    // In real code, setup code/data segments, stack, and IP/SP to begin 16-bit execution.

    printf("Preparing to attempt vm86old call...\n");

    // 2. Execute the system call
    // We use vm86old() for simplicity in demonstration.
    int ret = vm86old(&v86_context);

    if (ret == -1) {
        // 3. Handle errors
        if (errno == ENOSYS) {
            fprintf(stderr, "Error: vm86() call is not implemented on this architecture (ENOSYS).\n");
        } else if (errno == EFAULT) {
            fprintf(stderr, "Error: Invalid context pointer or structure access (EFAULT).\n");
        } else if (errno == EPERM) {
            fprintf(stderr, "Error: Permission or kernel state issue (EPERM).\n");
        } else {
            perror("vm86old failed unexpectedly");
        }
        return EXIT_FAILURE;
    }

    printf("vm86 entry point reached (or exited successfully).\n");
    // If successful, execution resumes here only after the VM86 task yields control back.
    return EXIT_SUCCESS;
}
